import {Label, Link, RelativeTime} from '@primer/react'

type AlertDismisser = {
  url: string
  name: string
  label: 'bot' | 'AI' | 'mannequin' | null
}

export type TrailingMessageProps = {
  showDismissMetadata: boolean
  alertDismisser: AlertDismisser | null
  alertDismissedAt: string | null
  showAutoDismissMetadata: boolean
  alertLastStateChangeAt: string | null
  showFixedMetadata: boolean
  alertFixedAt: string | null
}

export const TrailingMessage = ({
  showDismissMetadata,
  alertDismisser,
  alertDismissedAt,
  showAutoDismissMetadata,
  alertLastStateChangeAt,
  showFixedMetadata,
  alertFixedAt,
}: TrailingMessageProps) => {
  if (showDismissMetadata) {
    return (
      <>
        {alertDismisser ? (
          <>
            <span>dismissed by</span>{' '}
            <Link className="text-bold" href={alertDismisser.url} inline muted>
              {alertDismisser.name}
            </Link>
            {alertDismisser.label && (
              <>
                {' '}
                <Label variant="secondary">{alertDismisser.label}</Label>
              </>
            )}
          </>
        ) : (
          'Dismissed'
        )}
        <SpacedRelativeTime date={alertDismissedAt} />
      </>
    )
  }

  if (showAutoDismissMetadata) {
    return (
      <>
        auto-dismissed by <span className="text-bold">dependabot</span> <Label variant="secondary">bot</Label>
        <SpacedRelativeTime date={alertLastStateChangeAt} />
      </>
    )
  }

  if (showFixedMetadata) {
    return (
      <>
        Fixed
        <SpacedRelativeTime date={alertFixedAt} />
      </>
    )
  }

  return null
}

const SpacedRelativeTime = ({date}: {date: string | null}) => {
  if (!date) return null

  return (
    <>
      {' '}
      <RelativeTime date={new Date(date)} />
    </>
  )
}
